KK = 'Kiếm Khách (The Masked Wanderer): white mask with icy-blue eye slit, long silver-cream ponytail, dark layered clothing with cyan rune marks, two icy-blue swords'
item(so='001', ten='kk-don4', tieu_de='Kiếm Khách – đòn 4 (nhát kết): 2 khung giữa F4→F5→F6', uu_tien='P0', dir='art/kiem-khach/don4', vitri='cap[0..2].clip.don4 (cả 3 cấp dùng chung thư mục don4)',
  cells=[4, None, 5, None, 6],
  viec='Vẽ **2 khung mới**: `moi-01` chèn SAU F4 (giữa F4 và F5), `moi-02` chèn SAU F5 (giữa F5 và F6).',
  dang='"F4→F5→F6 đổi hình mạnh; chân trượt 10%; F6≈F7≈F8 vệt đứng hình. Khoá chân F0–F4; thêm 1–2 khung giữa (kiếm 1/3 và 2/3 quỹ đạo); F7–F8 vệt mảnh dần."',
  chi_tiet=['moi-01 (giữa F4–F5): kiếm ở ~1/3 quỹ đạo chém bổ – từ trên đầu vung ra trước, lưỡi chéo lên phía trước ~45°; thân bắt đầu gập tới; chân giữ nguyên chỗ như F4 (khoá chân); vệt chém mới chớm, mảnh.',
            'moi-02 (giữa F5–F6): kiếm ở ~2/3 quỹ đạo – lưỡi gần ngang chĩa trước-xuống; thân hạ thấp gần như F6; vệt cung cyan dài hơn F5 nhưng chưa chạm đất như F6.',
            'Chân trụ đúng chỗ khung trước/sau, không trượt.'],
  prompt='This strip shows consecutive frames of a 2D side-view pixel-art sword finisher of ' + KK + '. Draw ONLY the 2 missing in-between frames for the 2 empty dashed cells: cell 2 = sword at 1/3 of the overhead slash arc (blade swinging forward, ~45 degrees up-front, body starting to lean in, faint thin cyan trail); cell 4 = sword at 2/3 of the arc (blade almost horizontal pointing forward-down, body low like the next frame, cyan arc trail longer than frame 3 but not touching the ground). Feet stay planted exactly where they are in the neighbouring frames.',
  ra=['moi-01.png', 'moi-02.png'],
  thu_tu='F0 F1 F2 F3 F4 **moi-01** F5 **moi-02** F6 F7 F8 (11 khung)',
  ms='60, 65, 50, 40, 33, 33, 50, 33, 55, 60, 80 (559 ms; Claude chia từ bộ ChatGPT 60,65,50,40,35,65,55,60,80 – phiên chính có thể hỏi ChatGPT xác nhận khi vẽ)',
  su_kien='cả 3 cấp: so_hinh 9→11; trung [5,6,7]→[6,7,8,9]; lao [2,6,20]→[2,8,20]. Lớp sức mạnh (mat-na-nut-1/2/3, an-chuong-nguc) có thư mục don4 → phiên lắp tự đặt lớp cho 2 khung mới bằng điểm neo đo (do-neo.py), không cần phiên chính vẽ lớp.')
item(so='002', ten='kk-dapdat', tieu_de='Kiếm Khách – đập đất: 1 khung chuyển giữa F3–F4', uu_tien='P0', dir='art/kiem-khach/dapdat', vitri='clip.dapdat',
  cells=[3, None, 4],
  viec='Vẽ **1 khung mới** `moi-01`, chèn SAU F3 (giữa F3 lao xuống và F4 chạm đất).',
  dang='"Khựng rõ F3→F4 (đảo người → chạm đất 1 bước). Thêm 1 khung chuyển giữa F3–F4 (thân gần ngang, chân hướng đất); gai đỉnh F5–F7 rồi thu."',
  chi_tiet=['Khung đúng lúc sắp chạm đất: thân gần ngang/đang gập xuống, chân hướng xuống đất, kiếm chĩa xuống sắp cắm; chân sát vạch đất (dấu +). Chưa có gai/bụi băng (gai bắt đầu ở F4).'],
  prompt='This strip shows consecutive frames of a 2D side-view pixel-art ground-pound (plunging sword strike) of ' + KK + '. Draw ONLY the missing in-between frame for the middle empty dashed cell: the instant just before impact - body folding down almost horizontal, legs pointing to the ground, swords pointing down about to hit, feet just at the ground line marked by "+". No ice spikes or impact effect yet.',
  ra=['moi-01.png'],
  thu_tu='F0 F1 F2 F3 **moi-01** F4 … F13 (15 khung)',
  ms='55, 55, 45, 45, 33, 45, 45, 45, 50, 55, 55, 55, 55, 70, 80 (798 ms; bộ ChatGPT 14 khung + 33 ms cho khung chuyển)',
  su_kien='so_hinh 14→15; khung_lao giữ 3 (F3 vẫn là khung giữ khi lao; khung mới là khung chạm đất đầu tiên); trung [4,5,6,7,8]→[5,6,7,8,9].')
item(so='003', ten='kk-chemkhong', tieu_de='Kiếm Khách – chém xoay trên không: 1 khung xoay giữa F2–F3', uu_tien='P0', dir='art/kiem-khach/chemkhong', vitri='cap[0..2].clip.chemkhong',
  cells=[2, None, 3],
  viec='Vẽ **1 khung mới** `moi-01`, chèn SAU F2 (giữa F2 và F3).',
  dang='"F2→F3→F4 xoay \'nhảy ảnh\'. Thêm 1 khung xoay giữa F2–F3 (và F3–F4 nếu cần)." (khung F3–F4 để ở yêu cầu P1 020)',
  chi_tiet=['Thân ở góc xoay nằm giữa F2 (lộn ngược) và F3 (cuộn người, đầu chúc xuống phải) – xoay thêm ~45°; vòng vệt cyan liền mạch giữa hai khung; tóc theo hướng xoay.'],
  prompt='This strip shows consecutive frames of a 2D side-view pixel-art mid-air spinning sword slash of ' + KK + '. Draw ONLY the missing in-between frame for the middle empty dashed cell: the body rotated halfway between the left frame and the right frame (about 45 degrees further in the spin), swords and the circular cyan slash trail continuing smoothly, hair following the spin. Same body centre position.',
  ra=['moi-01.png'],
  thu_tu='F0 F1 F2 **moi-01** F3 F4 F5 F6 (8 khung)',
  ms='50, 50, 45, 33, 50, 50, 65, 70 (413 ms; bộ ChatGPT + 33 ms khung xoay)',
  su_kien='cả 3 cấp: so_hinh 7→8; trung [2,3,4]→[2,3,4,5].')
item(so='004', ten='kk-chet', tieu_de='Kiếm Khách – chết: sửa F3 + 1 khung khuỵu giữa F3–F4', uu_tien='P0', dir='art/kiem-khach/chet', vitri='clip.chet',
  cells=[2, None, None, 4],
  viec='Vẽ **2 ảnh**: `thay-03` THAY khung F3 (F3 hiện gần trùng F2), và `moi-01` chèn SAU F3 (giữa F3 mới và F4).',
  dang='"F1→F2 đổi dáng lớn mà giữ 130ms; F2≈F3 khựng giữa lúc ngã; F3→F4 bị kéo xuống; F5≈F6 kéo dài. Thành 8 khung: thêm 1 khung khuỵu gối/hạ hông giữa F3–F4; sửa F3 cho khác F2; căn theo điểm chạm đất."',
  chi_tiet=['thay-03 (ô trống 1): vẫn quỳ như F2 nhưng hông hạ thấp hơn, đầu gục thêm, thân bắt đầu đổ tới – khác F2 rõ ràng.',
            'moi-01 (ô trống 2): khuỵu gối, hạ hông sát đất, thân đổ ra trước, tay chống/kiếm trượt dần – nửa đường giữa thay-03 và F4 (nằm sấp).',
            'Gối/chân chạm đất đúng vạch đất (dấu +), không bị kéo xuống.'],
  prompt='This strip shows consecutive frames of a 2D side-view pixel-art death animation of ' + KK + '. Draw ONLY the 2 missing frames for the 2 empty dashed cells, so the fall from kneeling (left) to lying face-down (right) is smooth: cell 2 = still kneeling but hips lower and head drooping more, body starting to tip forward (clearly different from the left frame); cell 3 = knees buckling, hips almost on the ground, torso falling forward halfway to the lying pose, swords sliding. Knees/feet on the same ground line marked by "+".',
  ra=['thay-03.png', 'moi-01.png'],
  thu_tu='F0 F1 F2 **thay-03** **moi-01** F4 F5 F6 (8 khung; F3 cũ chuyển sang tệp `art/muot-2/kk-chet/cu-f03.png` để lưu)',
  ms='50, 67, 67, 67, 83, 100, 100, 200 (734 ms, đúng bộ 8 khung ChatGPT; giữ khung cuối, không lặp)',
  su_kien='so_hinh 7→8.')
item(so='005', ten='kk-luot', tieu_de='Kiếm Khách – lướt: 2 khung đứng dậy giữa F4–F5', uu_tien='P0', dir='art/kiem-khach/luot', vitri='clip.luot',
  cells=[4, None, None, 5],
  viec='Vẽ **2 khung mới** `moi-01`, `moi-02`, chèn SAU F4 (giữa F4 thấp người và F5 đứng thẳng).',
  dang='"Dễ giật ở đoạn ra: từ thấp bật đứng trong 1 khung. Thêm 1–2 khung đứng dậy trung gian; giữ 2–3 khung lao (hold có chủ ý)."',
  chi_tiet=['moi-01: thân nâng lên ~1/3 – còn chúi tới, chân sau kéo lên, tóc vẫn bay ngang ra sau.',
            'moi-02: thân gần đứng (~2/3), chân về gần nhau, tóc rủ dần xuống; kiếm hạ dần về dáng F5.',
            'Chân trước đặt đúng vạch đất (dấu +).'],
  prompt='This strip shows consecutive frames of a 2D side-view pixel-art dash of ' + KK + ': left = low forward dash pose, right = standing recovery pose. Draw ONLY the 2 missing in-between frames for the 2 empty dashed cells: cell 2 = body rising about one third (still leaning forward, back leg pulling in, hair still streaming back); cell 3 = body almost upright (two thirds), feet coming together, hair starting to fall, swords lowering toward the right pose. Front foot on the ground line marked by "+".',
  ra=['moi-01.png', 'moi-02.png'],
  thu_tu='F0 F1 F2 F3 F4 **moi-01** **moi-02** F5 (8 khung)',
  ms='33, 33, 50, 50, 50, 33, 50, 67 (366 ms; bộ ChatGPT 33,33,50,50,50,67 + 33/50 cho 2 khung đứng dậy)',
  su_kien='so_hinh 6→8 (clip chạy theo tỉ lệ thời gian lướt – không có khung sự kiện). Lớp sức mạnh có thư mục luot → phiên lắp tự đặt lớp theo điểm neo đo.')
